function icon(name){return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.Overview}</svg>`}
const pages=['Overview','Investigations','Incident Replay','Network Topology','Hosts','Evidence Explorer','Reports','Settings'];
let page='Network Topology', overview={}, incidents=[], events=[], findings=[], graph={nodes:[],edges:[]}, activeIncident=null, selected=null, replayIndex=0, playing=false, search='', graphMode='3D';let timer=null, pan={x:0,y:0};
async function api(path,opts={}){const headers=new Headers(opts.headers||{}),access=sessionStorage.getItem('traceback.accessKey');if(access)headers.set('Authorization',`Bearer ${access}`);const r=await fetch('/api'+path,{...opts,headers});const data=await (r.headers.get('content-type')||'').includes('json')?r.json():r.text();if(!r.ok){const error=Error(data.error||`Request failed (${r.status})`);error.status=r.status;throw error}return data}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2700)}
function nav(){const groups=[['WORKSPACE',['Overview','Investigations','Incident Replay','Network Topology']],['EVIDENCE',['Hosts','Evidence Explorer','Reports']],['SYSTEM',['Settings']]];$('#nav').innerHTML=groups.map(([g,items])=>`<div class="nav-label">${g}</div>`+items.map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${icon(x)}<span class="label">${x}</span></button>`).join('')).join('');$$('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));}
async function load(){try{[overview,incidents]=await Promise.all([api('/overview'),api('/incidents').then(x=>x.items)]);activeIncident=incidents.find(i=>i.id===activeIncident)?.id||incidents[0]?.id||null;if(activeIncident)await loadIncident(activeIncident);selectedInvestigation=activeIncident;selectedReport=activeIncident;render()}catch(e){if(e.status===401){$('#content').innerHTML=`<section class="panel access-panel"><p class="panel-kicker">PRIVATE WORKSPACE</p><h1>Enter your access key</h1><p>Use the workspace key supplied by its owner. It stays in this browser tab.</p><form id="access-form"><label for="access-key">Access key</label><input id="access-key" type="password" autocomplete="current-password" required><button class="btn primary" type="submit">Unlock workspace</button></form><p id="access-error" role="alert">${sessionStorage.getItem('traceback.accessKey')?'That key was not accepted.':''}</p></section>`;return}$('#content').innerHTML=`<div class="empty">Unable to load workspace data. ${esc(e.message)}</div>`}}
async function loadIncident(id){activeIncident=id;const data=await api(`/incidents/${encodeURIComponent(id)}`);events=data.events;findings=data.findings;graph=data.graph}
