function head(title,sub,buttons=''){return `<div class="page-head"><div><p class="eyebrow">TRACEBACK / ${esc(page.toUpperCase())}</p><h1>${title}</h1><div class="subhead">${sub}</div></div><div class="actions">${buttons}</div></div>`}
