function controlIcon(name){const paths={first:'<path d="M19 20 9 12l10-8v16ZM5 19V5"/>',prev:'<path d="m19 20-10-8 10-8v16ZM5 19V5"/>',play:'<path d="m7 4 13 8-13 8V4Z"/>',pause:'<path d="M8 5h3v14H8zM15 5h3v14h-3z"/>',next:'<path d="m5 4 10 8-10 8V4Zm14 1v14"/>'};return `<svg class="control-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||''}</svg>`}
function incidentRows(items=incidents){return `<div class="incident-list">${items.map(i=>`<div class="incident-row" data-incident="${esc(i.id)}"><i class="severity-dot ${i.severity==='critical'?'critical':''}"></i><div><strong>${esc(i.title)}</strong><small>${esc(i.id)} &nbsp;·&nbsp; ${i.event_count} events &nbsp;·&nbsp; ${esc(i.created)}</small></div><span class="tag ${i.status==='open'?'open':''}">${esc(i.severity)}</span></div>`).join('')||'<div class="empty">No matching investigations.</div>'}</div>`}
function volumeSvg(){const buckets=Array(12).fill(0);events.forEach(e=>{const t=new Date(e.timestamp).getTime(),start=events.length?new Date(events[0].timestamp).getTime():t,end=events.length?new Date(events.at(-1).timestamp).getTime():t;const idx=end===start?0:Math.min(11,Math.floor((t-start)/(end-start)*11));buckets[idx]++});const max=Math.max(...buckets,1),w=700,h=130;const pts=buckets.map((v,i)=>`${i*w/11},${h-v/max*95}`).join(' ');return `<svg viewBox="-10 -5 ${w+20} ${h+15}" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#58d6ff" stop-opacity=".22"/><stop offset="1" stop-color="#58d6ff" stop-opacity="0"/></linearGradient></defs><path d="M0 ${h} L${pts.replaceAll(' ',' L')} L${w} ${h}Z" fill="url(#area)"/><polyline points="${pts}" fill="none" stroke="#58d6ff" stroke-width="2" vector-effect="non-scaling-stroke"/>${buckets.map((v,i)=>`<circle cx="${i*w/11}" cy="${h-v/max*95}" r="3" fill="#58d6ff"><title>${v} observed events</title></circle>`).join('')}</svg>`}
function overviewPage(){return `${head('Operational overview','A grounded view of imported evidence and active investigations.',b('＋ Import evidence','upload',true)+b('↺ Load sample','sample'))}<div class="metric-row"><div class="metric" data-goto="Investigations"><label>Total investigations</label><strong>${overview.incidents||0}</strong><small>From persisted local records</small></div><div class="metric" data-goto="Investigations"><label>High / critical</label><strong>${overview.critical_high||0}</strong><small>Severity assigned to investigations</small></div><div class="metric" data-goto="Hosts"><label>Observed endpoints</label><strong>${overview.hosts||0}</strong><small>Unique source and destination IPs</small></div><div class="metric" data-goto="Evidence Explorer"><label>Network events</label><strong>${overview.events||0}</strong><small>Across the local evidence store</small></div></div><div class="section-grid"><section class="panel"><div class="panel-head"><h2>Event volume · ${events.length} records</h2><span>UTC · OBSERVED</span></div><div class="chart-wrap">${volumeSvg()}<div class="chart-labels"><span>${events[0]?.timestamp?.slice(11,19)||'—'}</span><span>RECORDED EVENT TIME →</span><span>${events.at(-1)?.timestamp?.slice(11,19)||'—'}</span></div></div><div class="panel-head"><h2>Recent investigations</h2><button class="btn" data-goto="Investigations">View all →</button></div>${incidentRows(incidents.slice(0,4))}</section><section class="panel"><div class="panel-head"><h2>Current investigation</h2><span>LOCAL RECORD</span></div>${activeIncident?`<div class="inspect"><h3>${esc(incidents.find(i=>i.id===activeIncident)?.title||'')}</h3><div class="field"><label>Investigation</label><span>${esc(activeIncident)}</span></div><div class="field"><label>Evidence records</label><span>${events.length}</span></div><div class="field"><label>Analysis status</label><span>Derived from stored observations</span></div><div class="field"><label>Interpretation</label><span>Findings are rule-based indications; verify their cited events.</span></div><div style="padding-top:12px">${b('Open investigation →','investigations',true)}</div></div>`:'<div class="empty">No investigation selected.</div>'}</section></div>`}
function investigationsPage(){return `${head('Investigations','Search and open an evidence-backed incident.',b('＋ Import evidence','upload',true))}<div class="panel"><div class="data-toolbar"><input id="incident-search" placeholder="Filter by title or incident ID…"><select id="severity-filter"><option value="">All severities</option><option>critical</option><option>high</option><option>medium</option><option>informational</option></select><select id="status-filter"><option value="">All statuses</option><option>open</option><option>closed</option></select></div><div id="incident-list">${incidentRows()}</div></div>`}
function rowsTable(items){return `<div class="table-scroll"><table><thead><tr><th>UTC TIME</th><th>SOURCE</th><th>DESTINATION</th><th>PORT</th><th>PROTO</th><th>EVENT TYPE</th><th>REF</th></tr></thead><tbody>${items.map(e=>`<tr data-event="${esc(e.id)}"><td>${esc(e.timestamp)}</td><td>${esc(e.src_ip)}:${esc(e.src_port??'—')}</td><td>${esc(e.dst_ip)}:${esc(e.dst_port??'—')}</td><td>${esc(e.dst_port??'—')}</td><td>${esc(e.protocol)}</td><td>${esc(e.event_type)}</td><td>${esc(e.source_ref)}</td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No events match the current search.</div>'}</div>`}
function evidencePage(){const shown=events.filter(e=>!search||JSON.stringify(e).toLowerCase().includes(search.toLowerCase()));const e=selected?events.find(x=>x.id===selected):null;return `${head('Evidence explorer','Normalized event records retain their original source references.',b('＋ Import evidence','upload',true))}<div class="split"><section class="panel"><div class="data-toolbar"><input id="event-search" value="${esc(search)}" placeholder="Search IPs, protocol, event type…"><span class="mono">${shown.length} / ${events.length}</span></div><div id="events-table">${rowsTable(shown)}</div></section><aside class="panel"><div class="panel-head"><h2>Event inspector</h2><span>${e?'SELECTED':'NO SELECTION'}</span></div>${e?`<div class="inspect"><h3>${esc(e.event_type)}</h3>${[['Event ID',e.id],['Timestamp UTC',e.timestamp],['Source',e.src_ip],['Destination',e.dst_ip],['Source port',e.src_port],['Destination port',e.dst_port],['Protocol',e.protocol],['Length',e.length],['Severity',e.severity],['Source reference',e.source_ref],['Packet index',e.packet_index],['Incident',e.incident_id]].map(([k,v])=>`<div class="field"><label>${esc(k)}</label><span>${esc(v??'—')}</span></div>`).join('')}<button class="btn" data-goto="Incident Replay">Replay this incident →</button></div>`:'<div class="empty">Choose a row to inspect its normalized evidence.</div>'}</aside></div>`}
function findingsPanel(){return `<div class="panel"><div class="panel-head"><h2>Evidence-backed findings</h2><span>${findings.length} DERIVED</span></div>${findings.map(f=>`<div class="finding"><div class="tag">${esc(f.severity)} · ${esc(f.confidence)} confidence</div><h3>${esc(f.title)}</h3><p>${esc(f.explanation)}</p><p>${esc(f.interpretation)}</p><p>Rule <span class="mono">${esc(f.rule)}</span> · ${f.event_ids.length} supporting records · ${esc(f.time_start)} to ${esc(f.time_end)}</p><p class="evidence">${esc(f.event_ids.join(' · '))}</p><p>${esc(f.limitations)}</p></div>`).join('')||'<div class="empty">No configured heuristic has enough evidence.</div>'}</div>`}
function graphFallbackSvg(isReplay=false){const W=800,H=390,n=graph.nodes.length;if(!n)return '<div class="empty">No topology available.</div>';let pos={};graph.nodes.forEach((node,i)=>{const a=(-Math.PI/2)+(2*Math.PI*i/n);pos[node.id]={x:W/2+Math.cos(a)*Math.min(270,W*.35),y:H/2+Math.sin(a)*Math.min(125,H*.32)}});const activeSet=new Set(events.slice(0,replayIndex+1).flatMap(e=>[e.src_ip,e.dst_ip]));const edges=graph.edges.filter(e=>!isReplay||activeSet.has(e.source)&&activeSet.has(e.target));return `<svg viewBox="0 0 ${W} ${H}" id="graph-svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#71869a"/></marker></defs><g id="graph-pan" transform="translate(${pan.x} ${pan.y})">${edges.map(e=>{const a=pos[e.source],b=pos[e.target];if(!a||!b)return '';const midx=(a.x+b.x)/2,midy=(a.y+b.y)/2;return `<g><line class="edge ${e.suspicious?'suspicious':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" marker-end="url(#arrow)"/><text class="edge-label" x="${midx}" y="${midy-5}">${esc(e.protocol)} · ${esc(e.port??'—')} (${e.count})</text></g>`}).join('')}${graph.nodes.map(node=>{const p=pos[node.id],sel=selected===node.id,active=!isReplay||activeSet.has(node.id);return `<g class="node ${sel?'selected':''}" data-node="${esc(node.id)}" opacity="${active?1:.18}"><circle cx="${p.x}" cy="${p.y}" r="${node.external?10:node.kind==='infrastructure'?11:8}" fill="${sel?'#e9faff':node.external?'#ffb454':node.kind==='infrastructure'?'#8596ff':'#58d6ff'}" stroke="#10202b" stroke-width="4"/><text x="${p.x}" y="${p.y+25}" text-anchor="middle">${esc(node.id)}</text><title>${esc(node.kind)} · ${node.events} observed event references</title></g>`}).join('')}</g></svg>`}
