graphMode=localStorage.getItem('traceback.graphMode')||graphMode;
document.documentElement.dataset.density=localStorage.getItem('traceback.density')||'comfortable';

function incidentRows(items=incidents){return `<div class="incident-list">${items.map(i=>`<div class="incident-row ${selectedInvestigation===i.id?'chosen':''}" data-select-incident="${esc(i.id)}" tabindex="0"><i class="severity-dot ${i.severity==='critical'?'critical':''}"></i><div><strong>${esc(i.title)}</strong><small>${esc(i.id)} · ${i.event_count} events · ${esc(i.created)}</small></div><span class="tag ${i.status==='open'?'open':''}">${esc(i.severity)}</span></div>`).join('')||'<div class="empty">No matching investigations.</div>'}</div>`}
function volumeSvg(){const buckets=Array(12).fill(0),times=events.map(e=>new Date(e.timestamp).getTime()),start=Math.min(...times),end=Math.max(...times);events.forEach(e=>buckets[bucketIndex(e)]++);const max=Math.max(...buckets,1),w=720,h=150,pts=buckets.map((v,i)=>`${i*w/11},${h-v/max*110}`).join(' ');return `<svg viewBox="-12 -8 ${w+24} ${h+24}" preserveAspectRatio="none" role="img" aria-label="Event counts across recorded timestamps"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#63deff" stop-opacity=".32"/><stop offset="1" stop-color="#63deff" stop-opacity="0"/></linearGradient></defs><path d="M0 ${h} L${pts.replaceAll(' ',' L')} L${w} ${h}Z" fill="url(#area)"/><polyline points="${pts}" fill="none" stroke="#63deff" stroke-width="2" vector-effect="non-scaling-stroke"/>${buckets.map((v,i)=>{const a=start+(end-start)*i/11,stamp=v?events.find(e=>{const t=new Date(e.timestamp).getTime();return t>=a&&(i===11||t<=start+(end-start)*(i+1)/11)})?.timestamp:'No events';return `<circle class="volume-point" data-event-bucket="${i}" tabindex="0" role="button" aria-label="${v} events around ${stamp}" cx="${i*w/11}" cy="${h-v/max*110}" r="${eventBucket===i?6:4}"><title>${v} events · ${stamp||''} · Select to inspect records</title></circle>`}).join('')}</svg>`}
function bucketIndex(e){const times=events.map(x=>new Date(x.timestamp).getTime()),lo=Math.min(...times),hi=Math.max(...times),t=new Date(e.timestamp).getTime();return hi===lo?0:Math.min(11,Math.floor((t-lo)/(hi-lo)*11))}
function overviewPage(){const i=incidents.find(x=>x.id===selectedInvestigation)||incidents[0];return `${head('Investigation observatory','Follow recorded activity, review active cases, and move from signal to evidence.',b('Import evidence','upload',true)+b('Load sample','sample'))}<section class="observatory"><div class="observatory-copy"><p class="panel-kicker">LOCAL EVIDENCE · UTC ORDER</p><h2>See the connections.<br><em>Follow what happened.</em></h2><p>${overview.events||0} records · ${overview.hosts||0} endpoints across ${overview.incidents||0} saved investigations. Totals reflect the local evidence store.</p><div class="observatory-metrics"><span><b>${overview.critical_high||0}</b> HIGH / CRITICAL</span><span><b>${overview.hosts||0}</b> ENDPOINTS</span><span><b>${overview.events||0}</b> OBSERVATIONS</span></div></div><div class="observatory-scene">${graphSvg(false)}<span class="scene-caption">OBSERVED COMMUNICATIONS · ${esc(incidents.find(x=>x.id===activeIncident)?.title||'NO ACTIVE INVESTIGATION')}</span></div></section><div class="overview-lower"><section class="panel volume-panel"><div class="panel-head"><div><p class="panel-kicker">TEMPORAL DISTRIBUTION</p><h2>Event volume</h2></div><span>${events.length} EVENTS · ${events[0]?.timestamp?.slice(0,10)||'NO DATA'}</span></div><div class="chart-wrap">${volumeSvg()}<div class="chart-labels"><span>${events[0]?.timestamp?.slice(11,19)||'—'}</span><span>RECORDED EVENT TIME →</span><span>${events.at(-1)?.timestamp?.slice(11,19)||'—'}</span></div></div><div class="chart-note">Select a point to inspect its corresponding records.</div></section><section class="panel recent-panel"><div class="panel-head"><div><p class="panel-kicker">CASE FILES</p><h2>Recent investigations</h2></div><button class="btn" data-goto="Investigations">All cases →</button></div>${incidentRows(incidents.slice(0,5))}</section><aside class="panel preview-panel"><div class="panel-head"><div><p class="panel-kicker">SELECTED CASE</p><h2>Context preview</h2></div><span>LOCAL</span></div>${i?`<div class="inspect"><div class="preview-severity"><i class="severity-dot ${i.severity==='critical'?'critical':''}"></i>${esc(i.severity)} · ${esc(i.status)}</div><h3>${esc(i.title)}</h3><div class="field"><label>Case ID</label><span>${esc(i.id)}</span></div><div class="field"><label>Recorded events</label><span>${i.event_count}</span></div><div class="field"><label>Created UTC</label><span>${esc(i.created)}</span></div><button class="btn primary" data-open-incident="${esc(i.id)}">Open investigation →</button></div>`:'<div class="empty">Import evidence to create an investigation.</div>'}</aside></div>`}
function investigationsPage(){const i=incidents.find(x=>x.id===selectedInvestigation)||incidents[0];return `${head('Investigation library','Search saved case files and inspect scope before opening.',b('Import evidence','upload',true))}<div class="library-layout"><section class="panel library-list"><div class="panel-head"><div><p class="panel-kicker">CASE INDEX</p><h2>${incidents.length} investigations</h2></div><span>SELECT A ROW FOR CONTEXT</span></div><div class="data-toolbar"><input id="incident-search" placeholder="Search title or case ID…"><select id="severity-filter"><option value="">All severities</option><option>critical</option><option>high</option><option>medium</option><option>informational</option></select><select id="status-filter"><option value="">All statuses</option><option>open</option><option>closed</option></select></div><div id="incident-list">${incidentRows()}</div></section><aside class="panel case-preview"><div class="panel-head"><div><p class="panel-kicker">CASE PREVIEW</p><h2>Selected investigation</h2></div><span>${i?esc(i.id):'—'}</span></div>${i?`<div class="inspect"><span class="tag ${i.status==='open'?'open':''}">${esc(i.severity)} · ${esc(i.status)}</span><h3>${esc(i.title)}</h3><div class="field"><label>Observed records</label><span>${i.event_count}</span></div><div class="field"><label>Created UTC</label><span>${esc(i.created)}</span></div><div class="field"><label>Scope</label><span>Stored observations associated with this case file.</span></div><button class="btn primary" data-open-incident="${esc(i.id)}">Open incident replay →</button><button class="btn" data-report="${esc(i.id)}">Export report</button></div>`:'<div class="empty">Select a case to inspect its metadata.</div>'}</aside></div>`}
function hostsPage(){const shown=graph.nodes.filter(n=>!hostQuery||`${n.id} ${n.kind}`.toLowerCase().includes(hostQuery.toLowerCase())),n=graph.nodes.find(x=>x.id===selected),related=n?events.filter(e=>e.src_ip===n.id||e.dst_ip===n.id):[];return `${head('Endpoint index','Explore addresses observed in the selected investigation.',b('Open topology','topology',true))}<div class="hosts-layout"><section class="panel"><div class="panel-head"><div><p class="panel-kicker">OBSERVED ASSETS</p><h2>${shown.length} endpoints</h2></div><span>${graph.event_count||events.length} RECORDS</span></div><div class="data-toolbar"><input id="host-search" value="${esc(hostQuery)}" placeholder="Filter endpoint or type…"></div><div class="host-grid">${shown.map(x=>`<button class="host ${selected===x.id?'selected':''}" data-select-host="${esc(x.id)}"><span class="host-kind ${x.external?'external':x.kind==='infrastructure'?'infra':''}">${esc(x.kind)}</span><strong>${esc(x.id)}</strong><small>${x.events} event references</small></button>`).join('')||'<div class="empty">No observed endpoint matches that filter.</div>'}</div></section><aside class="panel host-preview"><div class="panel-head"><div><p class="panel-kicker">ENDPOINT CONTEXT</p><h2>${n?esc(n.kind):'Select an endpoint'}</h2></div><span>${n?n.events+' REFS':'—'}</span></div>${n?`<div class="inspect"><h3 class="mono">${esc(n.id)}</h3><div class="field"><label>Related records</label><span>${related.length}</span></div><div class="field"><label>Connected endpoints</label><span>${graph.edges.filter(e=>e.source===n.id||e.target===n.id).map(e=>esc(e.source===n.id?e.target:e.source)).filter((v,j,a)=>a.indexOf(v)===j).join('<br>')||'No observed links'}</span></div><button class="btn primary" data-host-evidence="${esc(n.id)}">Inspect related evidence →</button><button class="btn" data-goto="Network Topology">Focus in topology →</button></div>`:'<div class="inspector-empty"><span class="selection-cross">+</span><p>Select an observed endpoint to see its relationships and records.</p></div>'}</aside></div>`}
function evidenceItems(){return events.filter(e=>(!search||JSON.stringify(e).toLowerCase().includes(search.toLowerCase()))&&(!evidenceHost||e.src_ip===evidenceHost||e.dst_ip===evidenceHost)&&(eventBucket===null||bucketIndex(e)===eventBucket)).sort((a,b)=>{const x=a[evidenceSort.key],y=b[evidenceSort.key];return (x==null?1:y==null?-1:String(x).localeCompare(String(y),undefined,{numeric:true}))*evidenceSort.dir})}
function rowsTable(items){return `<div class="table-scroll"><table><thead><tr>${[['timestamp','UTC TIME'],['src_ip','SOURCE'],['dst_ip','DESTINATION'],['dst_port','PORT'],['protocol','PROTO'],['event_type','EVENT TYPE'],['source_ref','SOURCE REF']].map(([k,l])=>`<th><button class="sort-head" data-sort="${k}">${l}${evidenceSort.key===k?(evidenceSort.dir>0?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${items.map(e=>`<tr data-event="${esc(e.id)}" tabindex="0" role="button" aria-label="Inspect event ${esc(e.id)}" class="${selected===e.id?'chosen':''}"><td>${esc(e.timestamp)}</td><td>${esc(e.src_ip)}:${esc(e.src_port??'—')}</td><td>${esc(e.dst_ip)}:${esc(e.dst_port??'—')}</td><td>${esc(e.dst_port??'—')}</td><td>${esc(e.protocol)}</td><td>${esc(e.event_type)}</td><td>${esc(e.source_ref)}</td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No events match the current filters.</div>'}</div>`}
function evidencePage(){const all=evidenceItems(),size=25,max=Math.max(1,Math.ceil(all.length/size));evidencePageIndex=Math.min(evidencePageIndex,max-1);const shown=all.slice(evidencePageIndex*size,(evidencePageIndex+1)*size),e=selected?events.find(x=>x.id===selected):null;return `${head('Evidence explorer','Search and sort normalized records while keeping source references in view.',b('Import evidence','upload',true))}<div class="split evidence-layout"><section class="panel"><div class="data-toolbar"><input id="event-search" value="${esc(search)}" placeholder="Search addresses, protocol, type, source…"><span class="mono">${all.length} MATCHING / ${events.length}</span></div>${evidenceHost||eventBucket!==null?`<div class="filter-chips">${evidenceHost?`<button class="btn" data-clear-host>HOST ${esc(evidenceHost)} ×</button>`:''}${eventBucket!==null?`<button class="btn" data-clear-bucket>TIME BUCKET ${eventBucket+1} ×</button>`:''}</div>`:''}<div id="events-table">${rowsTable(shown)}</div><div class="pagination"><span>${all.length?evidencePageIndex*size+1:0}–${Math.min((evidencePageIndex+1)*size,all.length)} of ${all.length} records</span><button class="btn" data-evidence-page="-1" ${evidencePageIndex===0?'disabled':''}>Previous</button><button class="btn" data-evidence-page="1" ${evidencePageIndex>=max-1?'disabled':''}>Next</button></div></section><aside class="panel evidence-inspector"><div class="panel-head"><div><p class="panel-kicker">SOURCE RECORD</p><h2>Event inspector</h2></div><span>${e?esc(e.id):'NO SELECTION'}</span></div>${e?`<div class="inspect"><h3>${esc(e.event_type)}</h3>${[['Timestamp UTC',e.timestamp],['Source',e.src_ip],['Destination',e.dst_ip],['Source port',e.src_port],['Destination port',e.dst_port],['Protocol',e.protocol],['Length',e.length],['Severity',e.severity],['Source reference',e.source_ref],['Packet index',e.packet_index],['Incident',e.incident_id]].map(([k,v])=>`<div class="field"><label>${esc(k)}</label><span>${esc(v??'—')}</span></div>`).join('')}<button class="btn primary" data-replay-event="${esc(e.id)}">Replay this event →</button><button class="btn" data-host-evidence="${esc(e.src_ip)}">Inspect source endpoint →</button></div>`:'<div class="empty">Choose a row to inspect its available normalized fields.</div>'}</aside></div>`}
function reportsPage(){const i=incidents.find(x=>x.id===selectedReport)||incidents[0],loaded=activeIncident===i?.id;return `${head('Investigation reports','Review report scope and cited analysis before exporting the HTML deliverable.')}<div class="reports-layout"><section class="panel report-index"><div class="panel-head"><div><p class="panel-kicker">GENERATED FROM STORED RECORDS</p><h2>Available case reports</h2></div><span>${incidents.length} CASES</span></div>${incidents.map(x=>`<button class="report-row ${i?.id===x.id?'chosen':''}" data-select-report="${esc(x.id)}"><span><strong>${esc(x.title)}</strong><small>${esc(x.id)} · ${x.event_count} observations · ${esc(x.created)}</small></span><span class="tag">${esc(x.severity)}</span></button>`).join('')||'<div class="empty">No investigations available.</div>'}</section><aside class="panel report-preview"><div class="panel-head"><div><p class="panel-kicker">REPORT PREVIEW</p><h2>${i?esc(i.title):'No report selected'}</h2></div><span>${i?esc(i.severity):''}</span></div>${i?`<div class="inspect"><div class="field"><label>Scope</label><span>${esc(i.created)} · ${i.event_count} observed records</span></div><div class="field"><label>Status</label><span>${esc(i.status)}</span></div><div class="field"><label>Findings</label><span>${loaded?findings.length+' derived findings':'Select this case to load its findings'}</span></div>${loaded?findings.slice(0,3).map(f=>`<div class="finding"><h3>${esc(f.title)}</h3><p>${esc(f.explanation)}</p><p class="evidence">${f.event_ids.length} cited event IDs · ${esc(f.confidence)} confidence</p></div>`).join(''):''}<p class="report-note">The export includes incident identity, scope, analyst notes, findings, event timeline, and supported limitations.</p><button class="btn primary" data-report="${esc(i.id)}">Export HTML report →</button></div>`:'<div class="empty">Import evidence to generate a report.</div>'}</aside></div>`}
function settingsPage(){const density=document.documentElement.dataset.density||'comfortable';return `${head('Workspace settings','Browser display preferences and transparent data handling.')}<div class="settings-layout"><section class="panel"><div class="panel-head"><div><p class="panel-kicker">DISPLAY</p><h2>Workspace preferences</h2></div><span>THIS BROWSER</span></div><div class="settings-box"><label class="setting-row"><span><b>Information density</b><small>Adjust spacing in evidence and case lists.</small></span><select id="density-setting"><option value="comfortable" ${density==='comfortable'?'selected':''}>Comfortable</option><option value="compact" ${density==='compact'?'selected':''}>Compact</option></select></label><label class="setting-row"><span><b>Topology rendering</b><small>Choose the default scene for this browser.</small></span><select id="scene-setting"><option value="3D" ${graphMode==='3D'?'selected':''}>3D scene</option><option value="2D" ${graphMode==='2D'?'selected':''}>2D graph</option></select></label><div class="settings-feedback">Preferences save in this browser.</div></div></section><section class="panel"><div class="panel-head"><div><p class="panel-kicker">PERSISTENT DATA</p><h2>Storage and analysis</h2></div><span>${overview.storage?.toUpperCase()||'SQLITE'}</span></div><div class="settings-box">TraceBack stores imported records in ${overview.storage||'SQLite'}. Upload limit: 10 MB locally and 4 MB on Vercel. Supported formats: JSON, JSONL, CSV. PCAP parsing is not enabled.<br><br>Sample events are synthetic; loading them adds missing fixture records without deleting imported evidence.<div class="settings-facts"><span>${overview.events||0}<small>stored observations</small></span><span>${overview.incidents||0}<small>case files</small></span><span>${overview.hosts||0}<small>observed endpoints</small></span></div></div></section><section class="panel rule-panel"><div class="panel-head"><div><p class="panel-kicker">DETERMINISTIC HEURISTIC</p><h2>Rule transparency</h2></div><span>TCP PORT FAN-OUT</span></div><div class="settings-box">The rule triggers when one source contacts five or more distinct TCP destination ports within an incident. Its confidence label is moderate, not a probability. A scan does not prove intent, access, or compromise. Findings cite the stored event IDs used by the rule.</div></section></div>`}
let replaySpeed=1;
function replaySpeedControl(){return `<label class="speed-control">SPEED <select id="replay-speed" aria-label="Replay speed"><option value="0.5" ${replaySpeed===.5?'selected':''}>0.5×</option><option value="1" ${replaySpeed===1?'selected':''}>1×</option><option value="2" ${replaySpeed===2?'selected':''}>2×</option><option value="4" ${replaySpeed===4?'selected':''}>4×</option></select></label>`}
function replayPage(){const e=events[replayIndex];return `${head('Incident replay','Step through recorded evidence in timestamp order.',b(controlIcon('first')+'Start','first')+b(controlIcon('prev')+'Previous','prev')+b(controlIcon(playing?'pause':'play')+(playing?'Pause':'Play'),'play',true)+b(controlIcon('next')+'Next','next'))}<div class="replay-layout"><section class="panel"><div class="panel-head"><div><p class="panel-kicker">RECORDED EVENT SEQUENCE</p><h2>Topology at selected event</h2></div><span id="replay-count">${e?`${replayIndex+1} / ${events.length}`:'NO EVENTS'}</span></div><div class="replay-stage">${graphSvg(true)}</div><div class="replay-controls">${replaySpeedControl()}<span id="replay-time">${e?.timestamp?.slice(11,19)||'?'}</span><input id="replay-range" type="range" min="0" max="${Math.max(events.length-1,0)}" value="${replayIndex}" aria-label="Replay event position"><span id="replay-total">${events.length} EVENTS</span><button class="btn" data-action="prev" aria-label="Previous event">${controlIcon('prev')}</button><button class="btn" data-action="next" aria-label="Next event">${controlIcon('next')}</button></div><div class="topology-foot">Playback follows UTC event timestamps; no synthetic timing is used.</div></section><aside class="panel"><div class="panel-head"><div><p class="panel-kicker">SELECTED RECORD</p><h2>Evidence inspector</h2></div><span id="replay-event-id">${e?esc(e.id):'?'}</span></div><div id="replay-observation">${replayObservation(e)}</div></aside></div><div style="height:14px"></div>${findingsPanel()}`}
function topologyTimeline(){const e=events[replayIndex];return `<section class="panel topology-timeline"><div class="timeline-head"><div><p class="panel-kicker">EVENT REPLAY</p><strong id="topology-event-count">${e?`${replayIndex+1} / ${events.length}`:'NO EVENTS'}</strong></div><span id="topology-event-id">${esc(e?.id||'—')}</span></div><div class="timeline-event" id="topology-observation">${e?`<time>${esc(e.timestamp)}</time><b>${esc(e.event_type)}</b><span>${esc(e.src_ip)} → ${esc(e.dst_ip)} · ${esc(e.protocol)} / ${esc(e.dst_port??'—')}</span>`:'<span>No recorded events in this investigation.</span>'}</div><div class="timeline-controls">${replaySpeedControl()}<button class="btn icon" data-action="first" aria-label="First event">${controlIcon('first')}</button><button class="btn icon" data-action="prev" aria-label="Previous event">${controlIcon('prev')}</button><button class="btn primary icon" data-action="play" aria-label="Play or pause replay">${controlIcon(playing?'pause':'play')}</button><button class="btn icon" data-action="next" aria-label="Next event">${controlIcon('next')}</button><input id="topology-range" type="range" min="0" max="${Math.max(events.length-1,0)}" value="${replayIndex}" aria-label="Select replay event" ${events.length?'':'disabled'}><span class="timeline-time" id="topology-time">${esc(e?.timestamp?.slice(11,19)||'—')}</span></div></section>`}
document.addEventListener('change',e=>{if(e.target.id!=='replay-speed')return;replaySpeed=+e.target.value;if(playing){playing=false;action('play')}});
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const row=e.target.closest?.('[data-select-incident], [data-event], .node[data-node]');if(!row)return;e.preventDefault();row.click()});
document.addEventListener('submit',e=>{if(e.target.id!=='access-form')return;e.preventDefault();sessionStorage.setItem('traceback.accessKey',$('#access-key').value);load()});

function filterIncidents(){const q=$('#incident-search')?.value.toLowerCase()||'',s=$('#severity-filter')?.value||'',st=$('#status-filter')?.value||'',items=incidents.filter(i=>(!q||`${i.id} ${i.title}`.toLowerCase().includes(q))&&(!s||i.severity===s)&&(!st||i.status===st));$('#incident-list').innerHTML=incidentRows(items);$$('[data-select-incident]').forEach(el=>el.onclick=()=>{selectedInvestigation=el.dataset.selectIncident;render()})}
function bind(){bindBase();$$(".node[data-node]").forEach(el=>{el.setAttribute("tabindex","0");el.setAttribute("role","button")});$$('[data-select-incident]').forEach(el=>el.onclick=()=>{selectedInvestigation=el.dataset.selectIncident;render()});$$('[data-open-incident]').forEach(el=>el.onclick=async()=>{try{await loadIncident(el.dataset.openIncident);selectedInvestigation=el.dataset.openIncident;replayIndex=0;playing=false;clearInterval(timer);go('Incident Replay')}catch(e){toast(e.message)}});$$('[data-select-host]').forEach(el=>el.onclick=()=>{selected=el.dataset.selectHost;render()});if($('#host-search'))$('#host-search').oninput=e=>{hostQuery=e.target.value;const p=e.target.selectionStart;render();$('#host-search')?.focus();$('#host-search')?.setSelectionRange(p,p)};$$('[data-host-evidence]').forEach(el=>el.onclick=()=>{evidenceHost=el.dataset.hostEvidence;eventBucket=null;search='';evidencePageIndex=0;go('Evidence Explorer')});const chooseBucket=el=>{eventBucket=+el.dataset.eventBucket;evidenceHost=null;evidencePageIndex=0;go('Evidence Explorer')};$$('[data-event-bucket]').forEach(el=>{el.onclick=()=>chooseBucket(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseBucket(el)}}});$$('[data-clear-host]').forEach(el=>el.onclick=()=>{evidenceHost=null;render()});$$('[data-clear-bucket]').forEach(el=>el.onclick=()=>{eventBucket=null;render()});$$('[data-evidence-page]').forEach(el=>el.onclick=()=>{evidencePageIndex+=+el.dataset.evidencePage;render()});$$('[data-sort]').forEach(el=>el.onclick=()=>{const key=el.dataset.sort;evidenceSort={key,dir:evidenceSort.key===key?-evidenceSort.dir:1};evidencePageIndex=0;render()});if($('#event-search'))$('#event-search').oninput=e=>{search=e.target.value;evidencePageIndex=0;const p=e.target.selectionStart;render();$('#event-search')?.focus();$('#event-search')?.setSelectionRange(p,p)};$$('[data-replay-event]').forEach(el=>el.onclick=()=>{const idx=events.findIndex(e=>e.id===el.dataset.replayEvent);if(idx>=0)replayIndex=idx;go('Incident Replay')});$$('[data-select-report]').forEach(el=>el.onclick=async()=>{selectedReport=el.dataset.selectReport;try{await loadIncident(selectedReport);render()}catch(e){toast(e.message)}});$$('[data-event]').forEach(el=>el.onclick=()=>{selected=el.dataset.event;render()});$('#density-setting')?.addEventListener('change',e=>{document.documentElement.dataset.density=e.target.value;localStorage.setItem('traceback.density',e.target.value);toast('Display preference saved')});$('#scene-setting')?.addEventListener('change',e=>{graphMode=e.target.value;localStorage.setItem('traceback.graphMode',graphMode);render();toast('Topology preference saved')})}

nav();load();
